// 07 立方体を積んだ立体の表面積
const sqs = (x0: number, y0: number, n: number, col: string, fill: string, u = 24): E[] => Array.from({ length: n }, (_, i) => bx(x0 + i * u, y0, u, u, undefined, col, fill));
const stairs = (x0: number, y0: number, col: string, fill: string, u = 24): E[] => [...sqs(x0, y0, 3, col, fill, u), ...sqs(x0, y0 - u, 2, col, fill, u), ...sqs(x0, y0 - 2 * u, 1, col, fill, u)];
